  review_inventory_wave_advance: { status: 'gateEvidence', gateEvidence: true, ownershipClass: 'storyScopedMutating', allowedPhases: ['REVIEW'], destructiveRisk: 'metadata-write', reason: 'Persists a critic-certified complete discovery wave only when it added verified finding families, establishing the signed start boundary for the next unchanged-material wave without minting remediation authority.' },
  review_inventory_finalize: { status: 'gateEvidence', gateEvidence: true, ownershipClass: 'storyScopedMutating', allowedPhases: ['DEV', 'REVIEW', 'TEST'], destructiveRisk: 'metadata-write', reason: 'With an OPEN saturation epoch, mints a signed inventory-only receipt after required lanes terminate and a bounded wave adds zero verified families. With no OPEN epoch, writes a PRE_CERT inventory-completeness receipt bound to current hashes. Completeness is not PRE_CERT and authorizesTest stays false.' },
