  milestone_status: { status: 'supported', ownershipClass: 'readOnly', allowedPhases: 'all', destructiveRisk: 'none', reason: 'Read-only grouped ProofStory milestone status report. It projects existing milestone-ledger, checklist, verificationIntent, verificationEvidence, phase, and summary facts only; it rejects mutation-like flags before reads, creates no milestone storage, writes no evidence/summaries/review passes, launches no reviewers, advances no phase, and never claims automatic DONE, production, or remote Authority readiness.' },
