  global_control_status: { status: 'supported', ownershipClass: 'readOnly', allowedPhases: 'all', destructiveRisk: 'none', reason: 'Read-only global lifecycle control plane dashboard. It projects runtime closure, diagnostic-only admissibility waterline, and queue governance without mutating story metadata, evidence, lifecycle gates, queue exceptions, or authority state.' },
