  autopilot_resume: { status: 'supported', ownershipClass: 'storyScopedMutating', allowedPhases: 'all', destructiveRisk: 'metadata-write', reason: 'Replays the per-run autopilot checkpoint ledger and writes local resume projection metadata only. Healthy fresh runs may report M1 resume guidance; stale, corrupt, or unsafe runs fail closed. It does not restart workers, widen scope, auto-merge, verify receipts, or claim release readiness.' },
