  memory_benchmark_real_data: { memoryRetrieval: true, status: 'supported', ownershipClass: 'readOnly', allowedPhases: 'all', destructiveRisk: 'none', reason: 'Exports a real lifecycle data corpus/gold/query/result baseline from existing project artifacts. It does not mutate Proof-or-Stop lifecycle state; optional caller-requested outputDir writes non-authoritative benchmark artifacts and refuses lifecycle-managed story paths, fixture paths, and existing output files. Output is not lifecycle gate evidence, review pass, validation evidence, delivery check, receipt, vector DB, or production memory architecture.' },
