  graph: { status: 'supported', ownershipClass: 'readOnly', allowedPhases: 'all', destructiveRisk: 'none', reason: 'B-3e16: read-only story + evidence graph visualizer, deliberately allowed in every phase like status. Reads story state and writes only its search index under the user cache directory (keyed by a hash of the repo root), so it never mutates story metadata nor dirties the worktree that DONE gates on a clean tree.' },
  evaluate: { status: 'supported', ownershipClass: 'readOnly', storyWriteEffect: 'whenEvaluatorPromptEnvelope', allowedPhases: ['TEST'], destructiveRisk: 'metadata-write', reason: 'Evaluator setup is read-only unless a configured evaluator target uses full-envelope rollout; that mode persists a Story Prompt Envelope and is projected to storyScopedMutating before runtime/owner gates.' },
  evaluate_save: { status: 'gateEvidence', gateEvidence: true, ownershipClass: 'storyScopedMutating', allowedPhases: ['TEST'], destructiveRisk: 'metadata-write', reason: 'Persists evaluator evidence consumed by DONE checks.' },
  finding_add: { status: 'gateEvidence', gateEvidence: true, ownershipClass: 'reviewerWrite', allowedPhases: ['DEV', 'REVIEW'], destructiveRisk: 'metadata-write', reason: 'Writes reviewer finding evidence used by review gates, in DEV or REVIEW. Reviewer-lane write, exempt from the owner lease because it can only APPEND: the handler pushes one record under the story finding lock and never edits or removes an existing one (a pass-only record is normalized into an appended review-pass instead), it changes no phase, and every gate that SPENDS a finding — REVIEW to TEST through story_advance, and finding_resolve / finding_dismiss — is storyScopedMutating and therefore owner-gated. A reviewer-lane record must additionally bind to the current review run for its lane (assertCurrentReviewRunForEvidence). B-8df9 F-007: it is NOT exempt because of the signature. signFinding binds CONTENT (storyId / id / desc / severity / timestamp / reviewRound / reviewRunId, plus the optional read-evidence and gap-log components) and is exported source, so any process that can write findings.json can produce a valid _hash; the domain does not even contain the agent field, whose lane is bound indirectly through reviewRunId. A content checksum binds what was written, never who wrote it.' },
  finding_list: { status: 'supported', ownershipClass: 'readOnly', allowedPhases: 'all', destructiveRisk: 'none', reason: 'Read-only reviewer finding inspection; cluster-resolution writeback occurs only in the owner-gated validate path.' },
