  acceptance_matrix: { status: 'supported', ownershipClass: 'readOnly', allowedPhases: 'all', destructiveRisk: 'none', reason: 'Renders a deterministic observe-only ProofStory acceptance projection; writes no artifact and is not gate evidence.' },
  acceptance_topology_check: { status: 'gateEvidence', gateEvidence: true, ownershipClass: 'readOnly', allowedPhases: 'all', destructiveRisk: 'none', reason: 'Runs the canonical read-only PLAN structural evaluator; the independent default-observe proofStory.acceptanceTopologyGateMode controls only whether the same diagnostics block PLAN to DEV.' },
  acceptance_basis_generate: { status: 'gateEvidence', gateEvidence: true, ownershipClass: 'storyScopedMutating', allowedPhases: ['PLAN', 'DEV', 'REVIEW'], destructiveRisk: 'metadata-write', reason: 'Sole registered verifier writer for the durable signed PLAN acceptance coverage basis consumed by acceptance_topology_check and the PLAN to DEV structural gate. REVIEW is allowed because a scope-contract change during REVIEW staleness-invalidates the basis, and PLAN is unreachable from REVIEW (REPLAN belongs to DEV), so there would otherwise be no phase in which to regenerate it. B-3f3d F-114 corrected an earlier version of this note: review_inventory_finalize consumes a ReviewInventoryCriticReceipt written by review_inventory_critic_set, NOT the TopologyCriticReceiptV1 written by topology_critic_receipt_set, so the claimed chain from stale basis to blocked finalize was wrong. The widening is also inert for a story that already has a pre-review artifact, since proofstory.ts prefers the frozen preReviewBasisArtifact; it takes effect only via the nullish-coalescing fallback to planArtifact when none exists. Regeneration is safe here: the basis signature covers only structural bindings (scope-contract digest, closure files hash, story files hash) and never reviewer verdicts, so it cannot launder a review pass.' },
