  pre_review_check_read: { status: 'gateEvidence', gateEvidence: true, ownershipClass: 'readOnly', allowedPhases: 'all', destructiveRisk: 'none', reason: 'Read-only verification of the same signed pre-review artifact and canonical production verifier used by the lifecycle consumer.' },
  acceptance_rollout_report: { status: 'gateEvidence', gateEvidence: true, ownershipClass: 'storyScopedMutating', allowedPhases: ['DEV'], destructiveRisk: 'metadata-write', reason: 'Runs the registered real-Story cohort producer and is the sole writer of the signed verifier-derived Wave 4 rollout report; caller membership, metrics, verdict, thresholds, adapter identity, and quorum claims are forbidden.' },
  acceptance_rollout_report_read: { status: 'gateEvidence', gateEvidence: true, ownershipClass: 'readOnly', allowedPhases: 'all', destructiveRisk: 'none', reason: 'Read-only signature, freshness, frozen-membership, threshold, adapter, and full-3x2 verification of the persisted rollout report.' },
  acceptance_rollout_check: { status: 'gateEvidence', gateEvidence: true, ownershipClass: 'readOnly', allowedPhases: 'all', destructiveRisk: 'none', reason: 'Canonical flat-project rollout evaluator used unchanged by CLI diagnostics and transition-orchestrator; observe/warn/enforce share status and diagnostics while enforce alone blocks admission.' },
