export type KnownCommandName = keyof typeof COMMAND_POLICIES;

/**
 * Commands with a declared capability to create, mutate, recover, or discard
 * Story-system state. This capability is intentionally independent from owner
 * lease ownership: Story writes exist in owner, reviewer, dangerous, and shared
 * command classes. The inventory is derived from the canonical command policy:
 * the two intrinsic Story-writing ownership classes plus explicit effects for
 * the cross-class and conditional writers. Adding a command cannot require a
 * second hand-maintained capability list.
 */
export const STORY_WRITE_CAPABILITY_COMMANDS: readonly KnownCommandName[] = Object.freeze(
  Object.entries(COMMAND_POLICIES)
    .filter(([, policy]) =>
      policy.ownershipClass === 'storyScopedMutating'
      || policy.ownershipClass === 'reviewerWrite'
      || ('storyWriteEffect' in policy && policy.storyWriteEffect !== undefined))
    .map(([command]) => command as KnownCommandName),
);

const STORY_WRITE_CAPABILITY_COMMAND_SET: ReadonlySet<string> = new Set(STORY_WRITE_CAPABILITY_COMMANDS);

/** Intrinsic effective writers include admitted extensions; read-only projections stay exempt. */
export function commandRequiresAuthoritativeRuntime(
  command: string,
  effectiveOwnership: OwnershipClass | null,
): boolean {
  return effectiveOwnership !== null
    && effectiveOwnership !== 'readOnly'
    && (effectiveOwnership === 'storyScopedMutating'
      || effectiveOwnership === 'reviewerWrite'
      || STORY_WRITE_CAPABILITY_COMMAND_SET.has(command));
}

export function getCommandLifecyclePolicy(command: string): CommandPolicy | undefined {
  return COMMAND_POLICIES[command as KnownCommandName];
}

export const getCommandPolicy = getCommandLifecyclePolicy;

